const DEADLINE = Date.parse('2026-10-23T13:32:45.227Z');
let rat = sdk.findNearbyNpc(/^giant rat$/i);
if (rat) {
  console.log('attacking', rat.name);
  try { await bot.attack(rat, 4000); } catch (e) {}
  const idx = rat.index;
  while (Date.now() < DEADLINE - 3000) {
    if (!sdk.getNearbyNpc(idx)) { console.log('KILL Giant rat'); break; }
    const p = sdk.getState()?.player;
    if (p && !p.combat.inCombat && sdk.getNearbyNpc(idx)) { try { await bot.attack(sdk.getNearbyNpc(idx), 3000); } catch (e) {} }
    await sdk.waitForTicks(2);
  }
}
return 'end msLeft ' + (DEADLINE - Date.now());
